package in.sevasetu.amc.web;
import in.sevasetu.amc.security.CurrentUser;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.time.Instant;import java.util.*;
@RestController @RequestMapping("/api/job-cards") public class JobCardController{private final JdbcClient db;public JobCardController(JdbcClient db){this.db=db;}public record Card(UUID id,UUID branchId,String branchName,UUID orderId,String billNumber,UUID chefEmployeeId,String chefName,String title,String notes,Instant dueAt,String priority,String status){}public record Create(@NotNull UUID branchId,UUID orderId,UUID chefEmployeeId,@NotBlank String title,String notes,Instant dueAt,@Pattern(regexp="NORMAL|HIGH|URGENT")String priority){}
 @GetMapping List<Card> list(@AuthenticationPrincipal CurrentUser u){CustomerController.tenant(u);return db.sql("select j.id,j.branch_id,b.name branch_name,j.order_id,o.bill_number,j.chef_employee_id,e.name chef_name,j.title,j.notes,j.due_at,j.priority,j.status from amcservice.job_cards j join amcservice.branches b on b.id=j.branch_id left join amcservice.orders o on o.id=j.order_id left join amcservice.employees e on e.id=j.chef_employee_id where j.tenant_id=:t order by case j.status when 'IN_PROGRESS' then 1 when 'ASSIGNED' then 2 when 'OPEN' then 3 else 4 end,j.due_at nulls last").param("t",u.tenantId()).query(Card.class).list();}
 @PostMapping @ResponseStatus(HttpStatus.CREATED) Card create(@AuthenticationPrincipal CurrentUser u,@Valid @RequestBody Create r){CustomerController.tenant(u);var branch=db.sql("select name from amcservice.branches where id=:b and tenant_id=:t").param("b",r.branchId()).param("t",u.tenantId()).query(String.class).optional().orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Branch not found"));String chef=null;if(r.chefEmployeeId()!=null)chef=db.sql("select name from amcservice.employees where id=:e and tenant_id=:t and branch_id=:b and job_role='CHEF' and active").param("e",r.chefEmployeeId()).param("t",u.tenantId()).param("b",r.branchId()).query(String.class).optional().orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Chef is unavailable"));var id=UUID.randomUUID();var status=r.chefEmployeeId()==null?"OPEN":"ASSIGNED";db.sql("insert into amcservice.job_cards(id,tenant_id,branch_id,order_id,chef_employee_id,title,notes,due_at,priority,status,created_by) values(:id,:t,:b,:o,:chef,:title,:notes,:due,:priority,:status,:u)").param("id",id).param("t",u.tenantId()).param("b",r.branchId()).param("o",r.orderId()).param("chef",r.chefEmployeeId()).param("title",r.title()).param("notes",r.notes()).param("due",r.dueAt()).param("priority",r.priority()).param("status",status).param("u",u.userId()).update();return new Card(id,r.branchId(),branch,r.orderId(),null,r.chefEmployeeId(),chef,r.title(),r.notes(),r.dueAt(),r.priority(),status);}
 @PatchMapping("/{id}/status") void status(@AuthenticationPrincipal CurrentUser u,@PathVariable UUID id,@RequestParam @Pattern(regexp="OPEN|ASSIGNED|IN_PROGRESS|READY|COMPLETED|CANCELLED")String value){CustomerController.tenant(u);if(db.sql("update amcservice.job_cards set status=:s,updated_at=now() where id=:id and tenant_id=:t").param("s",value).param("id",id).param("t",u.tenantId()).update()==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Job card not found");}
}
